/* 리커트 5점: 왼쪽(그렇다)=레드 → 가운데 회색 → 오른쪽(그렇지 않다)=오렌지 */
const SCALE = [
  { size: 32, color: T.red400 },
  { size: 30, color: "#f37a63" },
  { size: 26, color: "#d9d9d9" },
  { size: 30, color: "#f8ad84" },
  { size: 32, color: T.orange300 },
];

/* ── 공통 파츠 ────────────────────────────────────────────────────── */
