/* ── 앱 셸 ────────────────────────────────────────────────────────── */
/* answers는 gi(0~19, 화면 노출 순서=Q01~Q20)를 키로, LikertRow의 버튼 인덱스(0~4)를 값으로 저장한다.
   버튼 인덱스 0=가장 왼쪽("그렇다")이라 Likert 5점("매우 그렇다")에 대응하므로 5-index로 변환한다. */
function buildMvtiPayload(answers, freeText) {
  const out = {};
  for (let gi = 0; gi < 20; gi++) {
    const key = `Q${String(gi + 1).padStart(2, "0")}`;
    const idx = answers[gi];
    out[key] = idx == null ? null : 5 - idx;
  }
  return { answers: out, natural_language: freeText.trim() };
}

const MVTI_API_BASE = "http://localhost:8000";

/* api.py의 POST /mvti/score 호출 -> { type_code, axis_scores, type_name, keywords, characters } */
async function submitMvti(payload) {
  console.log("[MVTI 제출 payload]", JSON.stringify(payload, null, 2));
  try {
    const res = await fetch(`${MVTI_API_BASE}/mvti/score`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ answers: payload.answers }),
    });
    if (!res.ok) {
      console.error("[MVTI 채점 실패]", res.status, await res.text());
      return null;
    }
    const data = await res.json();
    console.log("[MVTI 채점 결과]", data);
    return data;
  } catch (err) {
    console.error("[MVTI 채점 요청 에러 - 백엔드(uvicorn api:app)가 켜져 있는지 확인]", err);
    return null;
  }
}

export default function App() {
  const [screen, setScreen] = useState("intro"); // 'intro' | 0..3 | 'freetext' | 'loading' | 'result'
  const [answers, setAnswers] = useState({});
  const [freeText, setFreeText] = useState("");
  const [scale, setScale] = useState(1);
  const [mvtiResult, setMvtiResult] = useState(null);

  useEffect(() => {
    const fit = () => setScale(Math.min(1, (window.innerHeight - 24) / 800, (window.innerWidth - 24) / 360));
    fit();
    window.addEventListener("resize", fit);
    return () => window.removeEventListener("resize", fit);
  }, []);

  const handleNext = () => {
    if (typeof screen === "number") {
      if (screen === PAGES.length - 1) setScreen("freetext");
      else setScreen(screen + 1);
    } else if (screen === "freetext") {
      const payload = buildMvtiPayload(answers, freeText);
      submitMvti(payload).then(setMvtiResult);
      setScreen("loading");
    }
  };
  const handleBack = () => {
    if (screen === 0) setScreen("intro");
    else if (screen === "freetext") setScreen(PAGES.length - 1);
    else if (screen === "loading") setScreen("freetext");
    else if (screen === "result") setScreen("freetext");
    else if (typeof screen === "number") setScreen(screen - 1);
  };

  return (
    <div style={{ minHeight: "100vh", background: "#ececec", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT }}>
      <div style={{ width: 360, height: 800, transform: `scale(${scale})`, transformOrigin: "center", background: "#fff", borderRadius: 24, overflow: "hidden", boxShadow: "0 12px 40px rgba(0,0,0,0.18)" }}>
        {screen === "intro" && <IntroScreen onStart={() => setScreen(0)} />}
        {typeof screen === "number" && (
          <QuestionScreen
            page={screen}
            answers={answers}
            onAnswer={(gi, v) => setAnswers((a) => ({ ...a, [gi]: v }))}
            onBack={handleBack}
            onNext={handleNext}
          />
        )}
        {screen === "freetext" && (
          <FreeTextScreen
            value={freeText}
            onChange={setFreeText}
            onBack={handleBack}
            onNext={handleNext}
            onSkip={handleNext}
          />
        )}
        {screen === "loading" && <LoadingFinalScreen onBack={handleBack} onDone={() => setScreen("result")} />}
        {screen === "result" && <ResultScreen onBack={handleBack} result={mvtiResult} />}
      </div>
    </div>
  );
}